<h2 class="h2 hs"><span class="lw"><span class="hm"><span class="hc" style="--i:0">Ч</span></span><span class="hm"><span class="hc" style="--i:1">а</span></span><span class="hm"><span class="hc" style="--i:2">с</span></span><span class="hm"><span class="hc" style="--i:3">т</span></span><span class="hm"><span class="hc" style="--i:4">і</span></span></span> <span class="hl-under"><span class="lw"><span class="hm"><span class="hc" style="--i:5">п</span></span><span class="hm"><span class="hc" style="--i:6">и</span></span><span class="hm"><span class="hc" style="--i:7">т</span></span><span class="hm"><span class="hc" style="--i:8">а</span></span><span class="hm"><span class="hc" style="--i:9">н</span></span><span class="hm"><span class="hc" style="--i:10">н</span></span><span class="hm"><span class="hc" style="--i:11">я</span></span></span></span></h2>
